insert into public.product_variants(product_id,sku,size,colour_en,colour_hex,stock_quantity,is_active) select id, 'TR-AC-303-ONE-SIZE-GOLD', 'One Size', 'Gold', '#B8974E', 40, true from public.products where slug='pearl-drop-earrings' on conflict (sku) do update set size=excluded.size,colour_en=excluded.colour_en,colour_hex=excluded.colour_hex,is_active=true;
