/*
TARA -- DEVELOPMENT SEED CATALOGUE

  DO NOT RUN THIS AGAINST PRODUCTION.

Fourteen invented products with Unsplash photography, fabricated ratings and
made-up customer reviews. They exist so that a developer working against a fresh
local database has something to lay out, filter, sort, page through and check
out with.

This used to be the last 140 lines of TARA_COMPLETE_SETUP.sql, which meant that
installing the production schema also installed the fake catalogue. It is now a
separate file that no migration references, and it is deliberately NOT named
`seed.sql` -- the Supabase CLI runs a file of that name automatically as part of
`supabase db reset`, and nothing should install demonstration products without
being asked to.

Run it on purpose, against a local or staging database only:

  psql "$LOCAL_DATABASE_URL" -f supabase/seed/development_seed.sql

To take the seed products back out again:

  delete from public.products where product_code like 'TR-%';

The delete cascades to their images, variants and reviews.
*/

begin;

-- Size values here are 'Unready', the current spelling of the placeholder for a
-- product sold as fabric. The SKUs still contain "UNDREADY" from an older
-- naming pass -- deliberately left alone, because a SKU is an opaque identifier
-- staff use to find stock, not a word anyone reads.

from public.categories c left join public.collections col on col.slug='festive' where c.slug='unstitched-three-piece'
on conflict (slug) do update set name_en=excluded.name_en,description_en=excluded.description_en,category_id=excluded.category_id,collection_id=excluded.collection_id,base_price=excluded.base_price,compare_at_price=excluded.compare_at_price,fabric_en=excluded.fabric_en,product_code=excluded.product_code,status=excluded.status,is_new=excluded.is_new,is_featured=excluded.is_featured,is_best_seller=excluded.is_best_seller,care_instructions_en=excluded.care_instructions_en,tags=excluded.tags,unstitched_details=excluded.unstitched_details,ready_made_details=excluded.ready_made_details;







